using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
public static class Angle90SavedAudit {
 public static ulong Hash(byte[] bytes) { unchecked { ulong h=14695981039346656037UL; foreach(byte b in bytes){h^=b;h*=1099511628211UL;} return h; } }
 public static byte[] Payload(string path) { var all=File.ReadAllBytes(path); using(var r=new BinaryReader(new MemoryStream(all))) {if(r.ReadUInt64()!=0x31504B434C524443UL)throw new Exception("wrapper magic:"+path);var n=r.ReadUInt64();var h=r.ReadUInt64();if(n!=(ulong)all.Length-24)throw new Exception("length:"+path);var bytes=r.ReadBytes((int)n);if(Hash(bytes)!=h)throw new Exception("checksum:"+path);return bytes;} }
 static float[] Floats(BinaryReader r) { var n=r.ReadUInt64();if(n>100000)throw new Exception("array bound");var x=new float[(int)n];for(int i=0;i<x.Length;i++){x[i]=r.ReadSingle();if(float.IsNaN(x[i])||float.IsInfinity(x[i]))throw new Exception("nonfinite float");}return x; }
 public sealed class Session { public string task; public int laneSize,countSize,update,actorSteps,criticSteps;public uint feedback;public ulong reliable,low;public uint measured,rejected;public int[] config;public float[] constants,actor,critic,actorM,actorV,criticM,criticV;public ulong initialWeights;public float[] initialCoefficients;public ulong gait,offset,starts,rng,worlds,counters,attempted,accepted,actions;public uint startsCount,horizons,clearance,posture,left,right;public ulong hash; }
 static int Adam(BinaryReader r,out float[] m,out float[] v){for(int i=0;i<5;i++){var x=r.ReadSingle();if(float.IsNaN(x)||float.IsInfinity(x))throw new Exception("Adam config");}var age=r.ReadInt32();m=Floats(r);v=Floats(r);if(age<0||m.Length!=v.Length||v.Any(x=>x<0))throw new Exception("Adam values");return age;}
 public static Session ReadSession(string path){var bytes=Payload(path);var s=new Session();s.hash=Hash(bytes);using(var r=new BinaryReader(new MemoryStream(bytes))){if(r.ReadUInt32()!=0x53535446||r.ReadUInt32()!=3)throw new Exception("session schema");var n=r.ReadUInt64();s.task=System.Text.Encoding.UTF8.GetString(r.ReadBytes((int)n));s.laneSize=(int)r.ReadUInt32();s.countSize=(int)r.ReadUInt32();s.config=new int[8];for(int i=0;i<8;i++)s.config[i]=r.ReadInt32();if(r.ReadUInt32()!=20261124)throw new Exception("seed");s.feedback=r.ReadUInt32();if(s.feedback!=2)throw new Exception("feedback mode");s.constants=new float[10];for(int i=0;i<10;i++)s.constants[i]=r.ReadSingle();r.ReadBytes(48);s.gait=r.ReadUInt64();s.offset=r.ReadUInt64();s.starts=r.ReadUInt64();s.initialWeights=r.ReadUInt64();s.initialCoefficients=new float[4];for(int i=0;i<4;i++)s.initialCoefficients[i]=r.ReadSingle();s.update=r.ReadInt32();s.actorSteps=r.ReadInt32();s.criticSteps=r.ReadInt32();s.rng=r.ReadUInt64();s.actor=Floats(r);s.critic=Floats(r);var a=Adam(r,out s.actorM,out s.actorV);var c=Adam(r,out s.criticM,out s.criticV);if(a!=s.actorSteps||c!=s.criticSteps)throw new Exception("Adam age");s.worlds=r.ReadUInt64();r.ReadBytes(checked((int)s.worlds*s.laneSize));s.counters=r.ReadUInt64();if(s.countSize!=72)throw new Exception("unknown counts layout");for(ulong i=0;i<s.counters;i++){s.attempted+=r.ReadUInt64();s.accepted+=r.ReadUInt64();s.actions+=r.ReadUInt64();s.reliable+=r.ReadUInt64();s.low+=r.ReadUInt64();s.startsCount+=r.ReadUInt32();s.horizons+=r.ReadUInt32();s.clearance+=r.ReadUInt32();s.posture+=r.ReadUInt32();s.left+=r.ReadUInt32();s.right+=r.ReadUInt32();s.measured+=r.ReadUInt32();s.rejected+=r.ReadUInt32();}if(r.BaseStream.Position!=r.BaseStream.Length)throw new Exception("trailing data");}return s;}
 public static float[] ReadActor(string path) {using(var r=new BinaryReader(new MemoryStream(Payload(path)))){if(r.ReadUInt32()!=0x4f594654||r.ReadUInt32()!=1)throw new Exception("actor schema");return Floats(r);}}
 public static bool Equal(byte[] a,byte[] b){return a.SequenceEqual(b);}
}


